-- ATTOZAP DISPAROS production schema for PostgreSQL + Prisma runtime.
CREATE TYPE "CompanyStatus" AS ENUM ('active','blocked');
CREATE TYPE "UserStatus" AS ENUM ('active','inactive','blocked');
CREATE TYPE "WhatsAppConnectionStatus" AS ENUM ('pending','qr_required','connected','disconnected','reconnecting','blocked','error');
CREATE TYPE "ContactStatus" AS ENUM ('valid','invalid','duplicate','blocked');
CREATE TYPE "CampaignStatus" AS ENUM ('draft','scheduled','running','paused','completed','canceled','failed');
CREATE TYPE "CampaignContactStatus" AS ENUM ('pending','queued','sending','sent','failed','skipped','canceled');
CREATE TYPE "MessageJobStatus" AS ENUM ('pending','queued','sending','sent','failed','skipped','canceled');

CREATE TABLE "Company" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "status" "CompanyStatus" NOT NULL DEFAULT 'active', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "role" TEXT NOT NULL, "status" "UserStatus" NOT NULL DEFAULT 'active', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "email"));
CREATE TABLE "WhatsAppConnection" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "phoneNumber" TEXT NOT NULL, "status" "WhatsAppConnectionStatus" NOT NULL DEFAULT 'pending', "qrCode" TEXT, "connectedAt" TIMESTAMP, "lastHeartbeatAt" TIMESTAMP, "messagesSent" INTEGER NOT NULL DEFAULT 0, "messagesReceived" INTEGER NOT NULL DEFAULT 0, "totalFailures" INTEGER NOT NULL DEFAULT 0, "dailyLimit" INTEGER NOT NULL DEFAULT 500, "hourlyLimit" INTEGER NOT NULL DEFAULT 60, "delayMinMs" INTEGER NOT NULL DEFAULT 12000, "delayMaxMs" INTEGER NOT NULL DEFAULT 45000, "sentToday" INTEGER NOT NULL DEFAULT 0, "sentThisHour" INTEGER NOT NULL DEFAULT 0, "healthScore" INTEGER NOT NULL DEFAULT 100, "sessionPath" TEXT NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "phoneNumber"));
CREATE TABLE "ContactList" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "source" TEXT NOT NULL, "totalContacts" INTEGER NOT NULL DEFAULT 0, "validContacts" INTEGER NOT NULL DEFAULT 0, "invalidContacts" INTEGER NOT NULL DEFAULT 0, "duplicateContacts" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Contact" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "listId" TEXT NOT NULL REFERENCES "ContactList"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "phone" TEXT NOT NULL, "rawPhone" TEXT NOT NULL, "tags" JSONB NOT NULL DEFAULT '[]', "customFields" JSONB NOT NULL DEFAULT '{}', "origin" TEXT NOT NULL, "status" "ContactStatus" NOT NULL DEFAULT 'valid', "validationError" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "listId", "phone"));
CREATE TABLE "MessageTemplate" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "name" TEXT NOT NULL, "body" TEXT NOT NULL, "mediaUrl" TEXT, "variables" JSONB NOT NULL DEFAULT '[]', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "connectionId" TEXT NOT NULL REFERENCES "WhatsAppConnection"("id"), "contactListId" TEXT NOT NULL REFERENCES "ContactList"("id"), "name" TEXT NOT NULL, "message" TEXT NOT NULL, "mediaUrl" TEXT, "status" "CampaignStatus" NOT NULL DEFAULT 'draft', "totalContacts" INTEGER NOT NULL DEFAULT 0, "totalSent" INTEGER NOT NULL DEFAULT 0, "totalDelivered" INTEGER NOT NULL DEFAULT 0, "totalFailures" INTEGER NOT NULL DEFAULT 0, "totalPending" INTEGER NOT NULL DEFAULT 0, "scheduledAt" TIMESTAMP, "startedAt" TIMESTAMP, "finishedAt" TIMESTAMP, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CampaignContact" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL, "campaignId" TEXT NOT NULL REFERENCES "Campaign"("id") ON DELETE CASCADE, "contactId" TEXT NOT NULL REFERENCES "Contact"("id") ON DELETE CASCADE, "status" "CampaignContactStatus" NOT NULL DEFAULT 'pending', "providerMessageId" TEXT, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "campaignId", "contactId"));
CREATE TABLE "MessageJob" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "campaignId" TEXT NOT NULL REFERENCES "Campaign"("id") ON DELETE CASCADE, "contactId" TEXT NOT NULL REFERENCES "Contact"("id"), "connectionId" TEXT NOT NULL REFERENCES "WhatsAppConnection"("id"), "message" TEXT NOT NULL, "mediaUrl" TEXT, "attempt" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL DEFAULT 3, "status" "MessageJobStatus" NOT NULL DEFAULT 'pending', "scheduledAt" TIMESTAMP NOT NULL, "idempotencyKey" TEXT NOT NULL, "queueJobId" TEXT NOT NULL, "providerMessageId" TEXT, "error" TEXT, "startedAt" TIMESTAMP, "sentAt" TIMESTAMP, "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("companyId", "idempotencyKey"));
CREATE TABLE "MessageLog" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "campaignId" TEXT REFERENCES "Campaign"("id") ON DELETE SET NULL, "connectionId" TEXT REFERENCES "WhatsAppConnection"("id") ON DELETE SET NULL, "messageJobId" TEXT, "contactId" TEXT REFERENCES "Contact"("id") ON DELETE SET NULL, "message" TEXT, "status" TEXT NOT NULL, "error" TEXT, "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "actorId" TEXT, "action" TEXT NOT NULL, "entityType" TEXT NOT NULL DEFAULT 'attozap', "entityId" TEXT, "payload" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX "User_companyId_status_idx" ON "User"("companyId", "status");
CREATE INDEX "User_companyId_createdAt_idx" ON "User"("companyId", "createdAt");
CREATE INDEX "WhatsAppConnection_companyId_status_idx" ON "WhatsAppConnection"("companyId", "status");
CREATE INDEX "WhatsAppConnection_companyId_createdAt_idx" ON "WhatsAppConnection"("companyId", "createdAt");
CREATE INDEX "ContactList_companyId_createdAt_idx" ON "ContactList"("companyId", "createdAt");
CREATE INDEX "Contact_companyId_status_idx" ON "Contact"("companyId", "status");
CREATE INDEX "Contact_companyId_createdAt_idx" ON "Contact"("companyId", "createdAt");
CREATE INDEX "Contact_companyId_listId_idx" ON "Contact"("companyId", "listId");
CREATE INDEX "MessageTemplate_companyId_createdAt_idx" ON "MessageTemplate"("companyId", "createdAt");
CREATE INDEX "Campaign_companyId_status_idx" ON "Campaign"("companyId", "status");
CREATE INDEX "Campaign_companyId_createdAt_idx" ON "Campaign"("companyId", "createdAt");
CREATE INDEX "Campaign_companyId_connectionId_idx" ON "Campaign"("companyId", "connectionId");
CREATE INDEX "CampaignContact_companyId_status_idx" ON "CampaignContact"("companyId", "status");
CREATE INDEX "CampaignContact_companyId_campaignId_idx" ON "CampaignContact"("companyId", "campaignId");
CREATE INDEX "MessageJob_companyId_status_idx" ON "MessageJob"("companyId", "status");
CREATE INDEX "MessageJob_companyId_campaignId_idx" ON "MessageJob"("companyId", "campaignId");
CREATE INDEX "MessageJob_companyId_createdAt_idx" ON "MessageJob"("companyId", "createdAt");
CREATE INDEX "MessageLog_companyId_campaignId_idx" ON "MessageLog"("companyId", "campaignId");
CREATE INDEX "MessageLog_companyId_type_idx" ON "MessageLog"("companyId", "type");
CREATE INDEX "MessageLog_companyId_createdAt_idx" ON "MessageLog"("companyId", "createdAt");
CREATE INDEX "AuditLog_companyId_createdAt_idx" ON "AuditLog"("companyId", "createdAt");
